k=np.arange(1,31);train=.55*np.exp(-k/9)+.06;test=.18+.42*np.exp(-k/6)+.0012*(k-10)**2;ax.plot(k,train,color=ACCENT,label='training error');ax.plot(k,test,color=BAD,label='out-of-sample error');j=np.argmin(test);ax.scatter([k[j]],[test[j]],color=GOOD,s=45,label='validation choice');ax.set_xlabel('model complexity');ax.set_ylabel('forecast error (illustrative)');ax.legend(fontsize=8);ax.set_title('More flexible is not always more predictive',loc='left')
